begin;set local lock_timeout='2s';set local statement_timeout='15s';do $guard$ declare n integer;begin select count(*) into n from public.raid_room_members where room_id='ee8b0e8a-1e25-43f1-bf09-30e37081d774' and user_id not in('fadc944c-0b15-472c-be4d-305c26d8163f','25975265-f042-4dd1-8ffc-a12f8414a035','5c53fd8d-245b-49da-8ca6-b7afd6b7e6f0');if n<>0 then raise exception 'non QA member';end if;perform 1 from public.raid_rooms where id='ee8b0e8a-1e25-43f1-bf09-30e37081d774' and owner_user_id='fadc944c-0b15-472c-be4d-305c26d8163f';if not found then raise exception 'QA room mismatch';end if;update public.users set raid_points=1 where id='5c53fd8d-245b-49da-8ca6-b7afd6b7e6f0' and raid_points=0;get diagnostics n=row_count;if n<>1 then raise exception 'QA RP expected0';end if;end $guard$;select now() observed_at,id,raid_points,raid_points_last_recovered_at from users where id='5c53fd8d-245b-49da-8ca6-b7afd6b7e6f0';commit;
